// <auto-generated />

using CompilerBase;
using VMLAssembler;

namespace CCompiler
{
    public partial class CodeGenerator
    {
        private void GenerateFunctionCall(FunctionCall funcCall)
        {
            int argSize = 0;  // 栈参数大小 (CCv2: 只计算第5+参数)
            // 检查内置函数
            if (funcCall.Name == "__builtin_va_start")
            {
                // va_start(ap, last_param)
                // ap = &last_param + 4 (4 bytes = 1 word)
                // Args[0] = ap (lvalue), Args[1] = last_param
                if (funcCall.Args.Count >= 2)
                {
                    // Get address of last_param
                    GenerateAddressOf(funcCall.Args[1]);
                    // Add 4 to get to first variadic arg
                    AddRI(OpCode.ADD, 0, 4);
                    AddRR(OpCode.MOVE, 1, 0);
                    GenerateLValueAddress(funcCall.Args[0]);
                    AddInstruction(OpCode.MOVE, Mem("R0"), Reg(1));
                }
                return;
            }
            else if (funcCall.Name == "__builtin_va_arg")
            {
                // va_arg(ap, type_size)
                // result = *ap; ap += type_size; return result
                if (funcCall.Args.Count >= 2)
                {
                    // Get ap value (current pointer)
                    GenerateExpression(funcCall.Args[0]);
                    // Save current pointer to R1
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0) }));
                    // Load value from *ap into R2 (saved result, R0 will be overwritten by type_size)
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 2), new Operand(OperandType.MEMORY, "R1") }));
                    // Calculate new ap = ap + type_size
                    GenerateExpression(funcCall.Args[1]); // type_size into R0
                    instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0) }));
                    // Store new ap back
                    GenerateLValueAddress(funcCall.Args[0]);
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.MEMORY, "R0"), new Operand(OperandType.REGISTER, 1) }));
                    // Return loaded value in R0
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.REGISTER, 2) }));
                }
                return;
            }
            else if (funcCall.Name == "__builtin_va_end")
            {
                // va_end(ap) - no-op in VML
                return;
            }
            else if (funcCall.Name == "__builtin_va_copy")
            {
                // va_copy(dest, src) - dest = src
                if (funcCall.Args.Count >= 2)
                {
                    GenerateExpression(funcCall.Args[1]); // src value into R0
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0) })); // save to R1
                    GenerateLValueAddress(funcCall.Args[0]); // dest address into R0
                    instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.MEMORY, "R0"), new Operand(OperandType.REGISTER, 1) }));
                }
                return;
            }
            else if (funcCall.Name == "getenv")
            {
                // getenv(name) -> SYSCALL 360 (GetEnv)
                if (funcCall.Args.Count < 1) { ReportArgCount("getenv", 1, funcCall.Args.Count); EmitUndefinedFallback(); return; }
                GenerateExpression(funcCall.Args[0]); // name string addr -> R0
                instructions.Add(new Instruction(OpCode.SYSCALL, new List<Operand> { new Operand(OperandType.IMMEDIATE, 360) }));
                // Result: R0 = address of value string (or 0 if not found)
                return;
            }
            else if (funcCall.Name == "setenv")
            {
                // setenv(name, value) -> SYSCALL 361 (SetEnv)
                if (funcCall.Args.Count < 2) { ReportArgCount("setenv", 2, funcCall.Args.Count); EmitUndefinedFallback(); return; }
                GenerateExpression(funcCall.Args[0]); // name string addr -> R0
                GenerateExpression(funcCall.Args[1]); // value string addr -> R1
                instructions.Add(new Instruction(OpCode.SYSCALL, new List<Operand> { new Operand(OperandType.IMMEDIATE, 361) }));
                // Result: R0 = error code (0=success)
                return;
            }
            else if (funcCall.Name == "exit")
            {
                // exit(n) -> MOVE R0, n; SYSCALL 3
                if (funcCall.Args.Count > 0)
                    GenerateExpression(funcCall.Args[0]);
                EmitExit();
                return;
            }
            else if (funcCall.Name == "get_platform")
            {
                // get_platform() -> SYSCALL 374
                instructions.Add(new Instruction(OpCode.SYSCALL, new List<Operand> { new Operand(OperandType.IMMEDIATE, 374) }));
                return;
            }
            else if (funcCall.Name == "PEEK")
            {
                // PEEK(addr) → CALL vml_peek (寄存器约定: R0=addr, 返回值 R0)
                if (funcCall.Args.Count < 1) { ReportArgCount("PEEK", 1, funcCall.Args.Count); EmitUndefinedFallback(); return; }
                GenerateExpression(funcCall.Args[0]);
                instructions.Add(new Instruction(OpCode.CALL, new List<Operand> { new Operand(OperandType.LABEL, "peek") }));
                return;
            }
            else if (funcCall.Name == "POKE")
            {
                // POKE(addr, val) → CALL vml_poke (寄存器约定: R0=val, R1=addr)
                if (funcCall.Args.Count < 2) { ReportArgCount("POKE", 2, funcCall.Args.Count); EmitUndefinedFallback(); return; }
                GenerateExpression(funcCall.Args[0]);  // addr → R0
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 1), new Operand(OperandType.REGISTER, 0) }));
                GenerateExpression(funcCall.Args[1]);  // val → R0
                instructions.Add(new Instruction(OpCode.CALL, new List<Operand> { new Operand(OperandType.LABEL, "poke") }));
                return;
            }

            // Get function definition to detect struct params
            Function funcDef = ast.Functions.FirstOrDefault(f => f.Name == funcCall.Name);
            bool[] isStructArg = new bool[funcCall.Args.Count];
            int[] structArgSizes = new int[funcCall.Args.Count];
            bool[] isDoubleArg = new bool[funcCall.Args.Count];
            bool[] isLongArg = new bool[funcCall.Args.Count];
            bool[] isFloatArg = new bool[funcCall.Args.Count];
            if (funcDef != null)
            {
                for (int i = 0; i < Math.Min(funcCall.Args.Count, funcDef.Params.Count); i++)
                {
                    if (IsStructParamType(funcDef.Params[i].Type))
                    {
                        isStructArg[i] = true;
                        structArgSizes[i] = GetTypeSizeFromString(funcDef.Params[i].Type);
                    }
                    else if (funcDef.Params[i].Type.Trim() == "double")
                    {
                        isDoubleArg[i] = true;
                    }
                    else if (funcDef.Params[i].Type.Trim() == "long"
                             || funcDef.Params[i].Type.Trim() == "long long"
                             || funcDef.Params[i].Type.Trim() == "unsigned long"
                             || funcDef.Params[i].Type.Trim() == "unsigned long long")
                    {
                        isLongArg[i] = true;
                    }
                    else if (funcDef.Params[i].Type.Trim() == "float")
                    {
                        isFloatArg[i] = true;
                    }
                }
            }
            // Fallback: infer isDoubleArg/isLongArg/isFloatArg from argument expression types
            // (handles both missing funcDef and type-string mismatches from parsed declarations)
            for (int i = 0; i < funcCall.Args.Count; i++)
            {
                if (!isDoubleArg[i] && !isLongArg[i] && !isFloatArg[i])
                {
                    if (funcCall.Args[i] is NumberLiteral nl)
                    {
                        // Check suffix first: L => long literal (even if Value overflowed to double)
                        // Use Contains to catch L/LL/UL/ULL/LU/LLU
                        if (nl.Suffix != null && nl.Suffix.IndexOf("L", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            isLongArg[i] = true;
                        }
                        else if (nl.Value is double d)
                        {
                            // Float literals in C use 'f' suffix
                            if (nl.Suffix != null && nl.Suffix.StartsWith("F", StringComparison.OrdinalIgnoreCase))
                                isFloatArg[i] = true;
                            else
                                isDoubleArg[i] = true;
                        }
                        else if (nl.Value is long l && (l < int.MinValue || l > int.MaxValue))
                            isLongArg[i] = true;
                    }
                }
            }

            // ── 可变参数默认提升：float → double（C 语义）──────────────────────────
            //
            // `printf("%f", x)` 里 x 无论是 float 还是 double，**到达 printf 时一律是 double**。
            // 本前端不做提升时：float 实参压 1 槽、double 压 2 槽 ⇒ printf 侧读到什么完全取决于
            // 实参的**静态类型**，运行期无从分辨。实测（改动前）：
            //     printf("%f", 1.5)      → `0.0`   （1.5 是 double，低字 0x00000000）
            //     printf("%f", x_float)  → `1.500000`（1 槽，位模式正好落在低字）
            // 现在 printf 侧按 C 定死「%f 读两槽 double」，所以在**调用点**把 float 提上去，
            // 那种"碰巧对"的写法才不会反过来变成乱码。
            //
            // 只提升**形参表覆盖不到的那一段**（`i >= Params.Count`）—— 固定形参有声明类型，
            // 该不该是 float 由声明说了算，不该被这里改写。
            if (funcDef != null && funcDef.IsVariadic)
            {
                for (int i = funcDef.Params.Count; i < funcCall.Args.Count; i++)
                {
                    // double 也要**显式**判一次：上面那条回退推断只认 `NumberLiteral`，
                    // 所以 `double z = 5.5; printf("%f", z)` 里 `z` 落不进 isDoubleArg
                    // ⇒ 被当成 4 字节 int 压栈（1 槽），而 printf 侧现在按 double 读 2 槽
                    // ⇒ 实测打出 `0.000000`。变参位置没有声明类型可依，只能按表达式推断。
                    var __at = InferExpressionType(funcCall.Args[i]);
                    if (!isStructArg[i] && !isDoubleArg[i] &&
                        (isFloatArg[i] || __at == ExprType.Float || __at == ExprType.Double))
                    {
                        isDoubleArg[i] = true;
                        isFloatArg[i] = false;
                    }
                }
            }

            // 间接调用判断:
            // 1. IsIndirectCall: Callee 不是简单 Identifier（如 *fp、arr[i]、obj.method）
            // 2. 函数指针变量调用: fp(42) 其中 fp 是已知的指针类型变量且不是已定义函数
            bool isIndirect = funcCall.IsIndirectCall;
            // 函数指针变量调用: 函数名不在已知函数表中，但在变量表中 → 间接调用
            if (!isIndirect && funcCall.Callee is Identifier id)
            {
                bool isKnownFunc = ast.Functions.Exists(f => f.Name == id.Name);
                bool isKnownVar = IsKnownVariable(id.Name);
                // indirect call detected via variable lookup
                if (!isKnownFunc && isKnownVar)
                    isIndirect = true;
            }
            bool indirectAddrPushed = false;
            if (isIndirect && funcCall.Callee != null)
            {
                GenerateExpression(funcCall.Callee);
                // ⚠ 被调地址必须**压栈**保存，不能留在 R8。
                //
                // 原注释写着「参数设置过程可能会使用 R0-R3」，那是「前 4 参走寄存器」时代的事实；
                // 现在实参全部压栈，但**实参求值本身**会用 R0-R11 当临时寄存器
                // （实测 `main` 的产物里就在用 R2/R5/R8/R11 给数组赋值暂存），
                // 留在 R8 里的地址必被冲掉 —— 表现是「调函数指针跳到随机的地址」。
                //
                // 压在最底下（先压），等全部实参压完后按 `[R13 + argSize]` 取回。
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));
                indirectAddrPushed = true;
            }

            // ══ 统一调用约定：全部实参右到左压栈、一个都不走寄存器、**调用方清栈** ══
            //
            // 原先是 cdecl / stdcall / pascal / fastcall / basic 五条分流，而其中
            // 「前 4 参走 R0-R3」与「两套清理约定」在 VML 里是**并存**的 ——
            // `Lib` 里 `vmlui` 家族（`ui_rect` …）是裸 `ret`（调用方清），
            // `builtins` 家族（`println_int` …）是 `add R13 #8`（被调方清）。
            // 调用点一旦猜错，**每调一次栈就漂一次**，症状是「同一个局部连读两遍得到不同的值」，
            // 极难反查（判据见 scripts/vml-abi-probe/，方案见 docs/VML调用约定统一.md）。
            //
            // 现在只留一条：**谁压的谁清**。它天然免疫三类问题 ——
            //   ① 变参函数：被调方原理上不知道调用方压了几个（真·stdcall 也是让变参退回 cdecl）；
            //   ② 函数指针间接调用：调用方拿不到被调方的形参个数；
            //   ③ 声明缺失或写错：调用方**总是**知道自己压了多少字节。
            //
            // `__stdcall` / `__cdecl` / `__fastcall` / `__pascal` 这些修饰符**仍然能被解析**
            // （`funcCall.Convention` / `funcDef.Convention` 照旧填），但**不再影响代码生成** ——
            // 这才符合「统一之后，写不写声明都必须是对的」。
            //
            // ⚠ 保留下来的那条老教训（它不随约定统一而失效）：
            // **实参求值之间不能夹带寄存器装载。** 表达式生成器用 R0/R1 做 push/pop 暂存，
            // 所以「边求值边 `MOVE Ri, R0`」会被**下一个**实参的求值冲掉，丢的还是先求值的那些。
            // 实测（历史）：`probe(p + 3*k, q + 3*k, 3*k)` 传出去是 R0=101 R1=**101**(应为 113)，
            // 五子棋的星位 `ui_circle(pad + 3*cell, padY + 3*cell, …)` 就是这么画歪的。
            // 现在全程不装寄存器，这个坑从结构上消失了；但**结构体返回的隐藏指针**仍要守这条规矩
            //（见下面 ②：它是**压栈**进去的，不是提前存进某个寄存器）。
            int totalArgs = funcCall.Args.Count;
            var argSizes = new int[totalArgs];

            // ① 只求值 + 压栈，从右到左（⇒ arg0 在最低地址 = 最后压入 = `[R12+12]`）
            for (int i = totalArgs - 1; i >= 0; i--)
            {
                if (isStructArg[i])
                {
                    PushStructToStack(funcCall.Args[i], structArgSizes[i]);
                    // ⚠ 必须按**向上取整到 4 的倍数**计账：PushStructToStack 是按「字」压的
                    //（末尾不足一字的部分也占一整格），按原始字节数计账会让清栈少弹一截。
                    argSizes[i] = ParamStackBytes(null, isStruct: true, structSize: structArgSizes[i]);
                }
                else
                {
                    GenerateExpression(funcCall.Args[i]);
                    // 与 ParamStackBytes 同源的 4/8 规则（见该函数注释）
                    int size = ParamStackBytes(funcDef?.Params.Count > i ? funcDef.Params[i].Type : null);
                    if (isDoubleArg[i] || isLongArg[i]) size = 8;
                    argSizes[i] = EmitPushArg(size, isFloatArg[i], isDoubleArg[i], isLongArg[i]);
                }
                argSize += argSizes[i];
            }

            // ② 结构体返回：调用方在自己的栈上留出返回区，并把地址**当 arg0 压进去**
            //    （原来走的是「提前 `move R9, R13`、最后 `move R0, R9`」那条寄存器路，
            //     而 R9 会在中间任意一次实参求值里被当临时寄存器用掉）。
            bool returnsStruct = funcDef != null && IsStructParamType(funcDef.ReturnType);
            if (returnsStruct)
            {
                int returnStructSize = GetTypeSizeFromString(funcDef.ReturnType);
                // 先留出返回区（SP 继续向下），再把它的地址压成 arg0
                instructions.Add(new Instruction(OpCode.SUB, new List<Operand> {
                    new(OperandType.REGISTER, 13), new(OperandType.IMMEDIATE, returnStructSize) }));
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> {
                    new(OperandType.REGISTER, 13) }));
                argSize += returnStructSize + 4;
            }

            // ③ 兼容层：把实参**同时**镜像进 R0-R3。
            //
            // ⚠ 这是给 `Lib` 里那 543 处内联汇编用的 —— 它们形如 `asm("SYSCALL #6")`
            //（参数直接吃 R0），把「第一个形参在 R0」**烙死在源码里**。
            // 掐掉这个镜像，那 500 多处就得逐个改源码才能活（配方是 `asm("SYSCALL #6, ${val}")`，
            // 见 docs/VML调用约定统一.md），而它们的收益只是「每次调用少 4 条指令」，
            // **没有任何用户可见的行为改善**。所以这里保留一份镜像：
            // 参数既按规范全部在栈上（清栈因此是统一的一条），也顺手复制进 R0-R3。
            //
            // 位置有讲究：必须**在所有实参求值完成之后**。表达式生成器用 R0/R1 做 push/pop 暂存，
            // 早装必被后一个实参的求值冲掉（本仓的历史伤：`probe(p + 3*k, q + 3*k, 3*k)`
            // 曾传出 R1=101 而非 113，五子棋星位就是这么画歪的）。
            // 现在压栈循环里一个寄存器都不碰，这里读的就是栈上的真值，天然免疫。
            {
                // 结构体返回时隐藏指针占了 [R13+0]，声明参数整体后移一格
                int shadowOff = returnsStruct ? 4 : 0;
                for (int i = 0; i < totalArgs && i < 4; i++)
                {
                    // 结构体参数不走寄存器（被调方也从栈读它们），只推进偏移
                    if (!isStructArg[i])
                    {
                        instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                            new Operand(OperandType.REGISTER, i),
                            new Operand(OperandType.MEMORY, $"R13+{shadowOff}") }));
                    }
                    shadowOff += argSizes[i];
                }
            }

            // ④ 间接调用：把最底下那格（被调地址）取回 R8
            //    —— 此刻 SP 已经停在「实参区之下」，被调地址正好在实参区上方一格。
            if (indirectAddrPushed)
            {
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> {
                    new Operand(OperandType.REGISTER, 8),
                    new Operand(OperandType.MEMORY, $"R13+{argSize}") }));
                argSize += 4;
            }

            // 使用函数的原始名称作为标签
            string funcLabel = ApplyVmlPrefix(funcCall.Name);

            // 调用函数（直接或间接）
            if (isIndirect)
            {
                instructions.Add(new Instruction(OpCode.CALL, new List<Operand> { new Operand(OperandType.REGISTER, 8) }));
            }
            else
            {
                instructions.Add(new Instruction(OpCode.CALL, new List<Operand> { new Operand(OperandType.LABEL, funcLabel) }));
            }

            // 清理参数栈 —— 统一约定下**永远是调用方清**（`argSize` 是刚才压进去的总字节数，
            // 含结构体返回区与间接调用的地址格）。被调方一律裸 `ret`，不再自己弹栈。
            if (argSize > 0)
            {
                instructions.Add(new Instruction(OpCode.ADD, new List<Operand> { new Operand(OperandType.REGISTER, 13), new Operand(OperandType.IMMEDIATE, argSize) }));
            }

            // 结果在 R0 中
        }

        /// <summary>
        /// 检查类型兼容性
        /// </summary>
        private bool IsTypeCompatible(ExprType targetType, ExprType valueType)
        {
            // 相同类型总是兼容
            if (targetType == valueType)
                return true;

            // 整数类型之间的兼容性
            var integerTypes = new HashSet<ExprType>
            {
                ExprType.Char, ExprType.UnsignedChar,
                ExprType.Short, ExprType.UnsignedShort,
                ExprType.Int, ExprType.UnsignedInt,
                ExprType.Long, ExprType.UnsignedLong,
                ExprType.LongLong, ExprType.UnsignedLongLong
            };

            // 浮点类型
            var floatTypes = new HashSet<ExprType> { ExprType.Float, ExprType.Double };

            // 指针类型
            var pointerTypes = new HashSet<ExprType>
            {
                ExprType.CharPtr, ExprType.ShortPtr, ExprType.IntPtr,
                ExprType.LongPtr, ExprType.FloatPtr, ExprType.DoublePtr,
                ExprType.VoidPtr
            };

            // 整数类型之间兼容（有符号和无符号可以相互转换）
            if (integerTypes.Contains(targetType) && integerTypes.Contains(valueType))
                return true;

            // 浮点类型之间兼容
            if (floatTypes.Contains(targetType) && floatTypes.Contains(valueType))
                return true;

            // 整数可以赋值给浮点
            if (floatTypes.Contains(targetType) && integerTypes.Contains(valueType))
                return true;

            // 浮点可以赋值给整数（会截断）
            if (integerTypes.Contains(targetType) && floatTypes.Contains(valueType))
                return true;

            // 指针类型兼容性
            if (pointerTypes.Contains(targetType))
            {
                // void* 可以接受任何指针类型
                if (targetType == ExprType.VoidPtr && pointerTypes.Contains(valueType))
                    return true;

                // 相同基类型的指针兼容
                if (targetType == valueType)
                    return true;
            }

            // 字符可以赋值给整数
            if (targetType == ExprType.Char && integerTypes.Contains(valueType))
                return true;

            if (valueType == ExprType.Char && integerTypes.Contains(targetType))
                return true;

            // 默认不兼容
            return false;
        }

        /// <summary>
        /// 获取类型名称
        /// </summary>
        private string GetTypeName(ExprType type)
        {
            switch (type)
            {
                case ExprType.Void: return "void";
                case ExprType.Char: return "char";
                case ExprType.UnsignedChar: return "unsigned char";
                case ExprType.Short: return "short";
                case ExprType.UnsignedShort: return "unsigned short";
                case ExprType.Int: return "int";
                case ExprType.UnsignedInt: return "unsigned int";
                case ExprType.Long: return "long";
                case ExprType.UnsignedLong: return "unsigned long";
                case ExprType.Float: return "float";
                case ExprType.Double: return "double";
                case ExprType.CharPtr: return "char*";
                case ExprType.ShortPtr: return "short*";
                case ExprType.IntPtr: return "int*";
                case ExprType.LongPtr: return "long*";
                case ExprType.FloatPtr: return "float*";
                case ExprType.DoublePtr: return "double*";
                case ExprType.VoidPtr: return "void*";
                case ExprType.Unknown: return "unknown";
                default: return type.ToString();
            }
        }

        /// <summary>
        /// 根据函数调用的参数构建签名（简化版本 - 只根据参数数量）
        /// </summary>
        private string BuildCallSignature(FunctionCall funcCall)
        {
            return $"{funcCall.Name ?? "indirect"}({funcCall.Args?.Count ?? 0})";
        }

        /// <summary>
        /// 规范化类型名称
        /// </summary>
        private string NormalizeTypeName(ExprType type)
        {
            switch (type)
            {
                case ExprType.Int: return "int";
                case ExprType.Char: return "char";
                case ExprType.Float: return "float";
                case ExprType.Double: return "double";
                case ExprType.Long: return "long";
                case ExprType.Short: return "short";
                case ExprType.IntPtr: case ExprType.LongPtr: case ExprType.VoidPtr: case ExprType.CharPtr: case ExprType.FloatPtr: case ExprType.DoublePtr: return "ptr";
                default: return "int";
            }
        }

        /// <summary>
        /// Push the contents of a struct expression onto the stack, word by word
        /// (from last word to first, so the first word ends up at the lowest address).
        /// R0 is destroyed; R10 is used as a temporary base pointer.
        /// </summary>
        private void PushStructToStack(ASTNode structExpr, int structSize)
        {
            // Get the address of the struct → R0
            if (structExpr is Identifier ident && variables.ContainsKey(ident.Name))
                GenerateAddressOf(structExpr);
            else if (structExpr is MemberAccess)
                GenerateMemberAddress((MemberAccess)structExpr);
            else
                GenerateAddress(structExpr);

            // R10 = struct base address (R10 is a volatile temp register)
            instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 10), new Operand(OperandType.REGISTER, 0) }));

            int numWords = (structSize + 3) / 4;
            int remainder = structSize % 4;
            if (remainder != 0)
            {
                // First push the partial word (highest address bytes)
                // For a 6-byte struct: bytes 4-5 (partial word at offset 4)
                instructions.Add(new Instruction(OpCode.MOVEH, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, $"R10+{structSize - remainder}") }));
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));
                numWords--;
            }
            // Push full words from last to first
            for (int w = numWords - 1; w >= 0; w--)
            {
                instructions.Add(new Instruction(OpCode.MOVE, new List<Operand> { new Operand(OperandType.REGISTER, 0), new Operand(OperandType.MEMORY, $"R10+{w * 4}") }));
                instructions.Add(new Instruction(OpCode.PUSH, new List<Operand> { new Operand(OperandType.REGISTER, 0) }));
            }
        }

        /// <summary>
        /// 一个形参在**调用方栈上**占多少字节 —— **调用点与被调方共用的唯一规则**。
        ///
        /// 规则：每个标量占一个 4 字节槽（与 ABI 基准「参数 4 字节对齐」一致），
        /// 64 位类型（double / long 系）占两格 8 字节，按值结构体按 4 字节向上取整。
        ///
        /// ⚠ **这段规则必须只有一处实现。** 原先调用方按「每参数 4 字节」推进，而被调方
        /// 用 `GetTypeSizeFromString` + `VarMemManager.AlignmentForSize` 的**自然大小与对齐**
        /// 分配（char=1、short=2）⇒ 两端不一致、形参整体错位，而且**不报错**。
        /// 实测就是脚本探针 p6：`mix(char, short, int, double, int)` 从第 2 个形参起全错；
        /// 单类型隔离后确认「char 过去是对的、short 开始错」。
        /// </summary>
        /// <param name="typeName">形参/实参的类型名（可为空）</param>
        /// <param name="isStruct">该类型是否为按值传递的结构体/联合体</param>
        /// <param name="structSize">按值结构体的实际大小（仅 isStruct 为真时使用）</param>
        private static int ParamStackBytes(string typeName, bool isStruct = false, int structSize = 0)
        {
            if (isStruct) return ((structSize + 3) / 4) * 4;

            string t = (typeName ?? "").ToLower().Trim();
            t = t.Replace("const", "").Replace("volatile", "").Replace("restrict", "").Trim();
            while (t.Contains("  ")) t = t.Replace("  ", " ");

            if (t == "double" || t == "long" || t == "long long"
                || t == "unsigned long" || t == "unsigned long long")
                return 8;

            // char / short / int / float / 指针 / 未知 —— 一律一个 4 字节槽
            return 4;
        }

        /// <summary>
        /// Check if the given type name is a struct/union type (by-value, not pointer).
        /// </summary>
        private bool IsStructParamType(string typeName)
        {
            if (string.IsNullOrEmpty(typeName)) return false;
            typeName = typeName.ToLower().Trim();
            typeName = typeName.Replace("const", "").Replace("volatile", "").Trim();
            // Pointer-to-struct is not a struct param (passed as regular int pointer)
            if (typeName.Contains('*')) return false;
            if (typeName.StartsWith("struct ") || typeName.StartsWith("union "))
                return true;
            // 检查 typedef 别名是否指向 struct/union
            if (typeAliases.TryGetValue(typeName, out var resolved))
            {
                if (resolved == "struct" || resolved == "union") return true;
                if (resolved.StartsWith("struct ") || resolved.StartsWith("union ")) return true;
            }
            return false;
        }
    }
}
